void mainImage( out vec4 fragColor, in vec2 fragCoord )
{

vec2 uv = fragCoord/iResolution.xy;
vec4 frame1 = texture(iChannel0, uv);
vec4 frame2 = texture(iChannel1, uv);

// Mix the frames with a weight of 0.05
vec4 mixedFrame = mix(frame1, frame2, 0.05);

// Extract the Y component (luminance) from frame1
float Y_frame1 = 0.299 * frame1.r + 0.587 * frame1.g + 0.114 * frame1.b;

// Extract the Y component from the mixed frame
float Y_mixed = 0.299 * mixedFrame.r + 0.587 * mixedFrame.g + 0.114 * mixedFrame.b;

// Compute the absolute difference between the Y components
float Y_delta = abs(Y_frame1 - Y_mixed);


vec4 Dynamic;
if ( (Y_delta>=0.0) && (Y_delta<0.0005))
  Dynamic = mix(frame1, frame2, 0.01);
else
  if ( (Y_delta>=0.0005) && (Y_delta<0.001))
    Dynamic = mix(frame1, frame2, 0.05);
  else
    if ( (Y_delta>=0.001) && (Y_delta<0.002))
      Dynamic = mix(frame1, frame2, 0.1);
    else
      if ( (Y_delta>=0.002) && (Y_delta<0.01))
        Dynamic = mix(frame1, frame2, 0.2);
      else
         Dynamic = mix(frame1, frame2, 0.5);


         // Normalized pixel coordinates (from 0 to 1)


    float szSlide = .001;        
    vec2 mouse =iMouse.xy/ iResolution.xy;
    if(mouse.x <= 0.0 &&  mouse.y <= 0.0) mouse.x = .5; // to show initial screen half splitted

	fragColor = uv.x<mouse.x-szSlide  ? Dynamic
          : (uv.x>mouse.x+szSlide ?  frame2
          :  vec4(1.0));


}
